#!/bin/bash\n\n# Color definitions for smg4OS setup\n\nRED='\\033[0;31m'\nGREEN='\\033[0;32m'\nYELLOW='\\033[1;33m'\nBLUE='\\033[0;34m'\nMAGENTA='\\033[0;35m'\nCYAN='\\033[0;36m'\nWHITE='\\033[1;37m'\nGOLD='\\033[38;5;220m'\nNC='\\033[0m'\n\n# SMG4 Functions\nsmg4_say() {\n    local message=\"$1\"\n    echo -e \"${GOLD}[SMG4]${NC} ${CYAN}$message${NC}\"\n}\n\nsmg4_warning() {\n    local message=\"$1\"\n    echo -e \"${RED}[SMG4]${NC} ${YELLOW}⚠️  $message${NC}\"\n}\n\nsmg4_success() {\n    local message=\"$1\"\n    echo -e \"${GREEN}[SMG4]${NC} ✓ $message${NC}\"\n}\n\nsmg4_error() {\n    local message=\"$1\"\n    echo -e \"${RED}[SMG4]${NC} ✗ ERROR: $message${NC}\"\n}\n"